15	import org.springframework.web.bind.annotation.RequestBody;
16	
17	/**
18	 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
19	 * required field ({@code firstName}, {@code lastName}, {@code address}, {@code city},
20	 * {@code telephone}), and also applies the DTO's declared format constraints. When any
21	 * field is invalid it throws {@link InvalidOwnerFieldsException} naming those fields, so
22	 * the response is a 400 listing them; otherwise it publishes the validated body for the
23	 * downstream build step. This is the pipeline's sole {@code @RequestBody} binding.
24	 */
25	public class ValidateOwnerFields {
26	
27	    /** Required fields in the order they should be reported, paired with their accessor. */
28	    private static Map<String, Supplier<String>> requiredFields(OwnerFieldsDto request) {
29	        Map<String, Supplier<String>> fields = new LinkedHashMap<>();
30	        fields.put("firstName", request::getFirstName);
31	        fields.put("lastName", request::getLastName);
32	        fields.put("address", request::getAddress);
33	        fields.put("city", request::getCity);
34	        fields.put("telephone", request::getTelephone);
35	        return fields;
36	    }
37	
38	    public void service(@RequestBody OwnerFieldsDto request, Validator validator,
39	            Out<OwnerFieldsDto> validated) throws InvalidOwnerFieldsException {
40	
41	        // Preserve field-declaration order and de-duplicate fields flagged more than once.
42	        Set<String> invalid = new LinkedHashSet<>();
43	
44	        // Required fields must be present and non-blank.
45	        requiredFields(request).forEach((name, accessor) -> {
46	            String value = accessor.get();
47	            if (value == null || value.isBlank()) {
48	                invalid.add(name);
49	            }
50	        });
51	
52	        // Present fields must still satisfy the DTO's declared constraints (size, pattern, ...).
53	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
54	            invalid.add(violation.getPropertyPath().toString());
55	        }
56	
57	        if (!invalid.isEmpty()) {
58	            throw new InvalidOwnerFieldsException(new ArrayList<>(invalid));
59	        }
60	
61	        validated.set(request);
62	    }
63	}
